class TestRewardBounds:
    @pytest.mark.parametrize("output_str", [
        "not json",
        "{}",
        json.dumps({"entities": [], "relations": []}),
        json.dumps({"entities": [{"type": "PER", "text": "x"}], "relations": []}),
